INSERT INTO tenant_theme_settings (tenant_id, brand_color, primary_color, heading_font, body_font, theme_config, shop_live, shop_ordering, shop_live_at, is_published, storefront_status, show_announcement_bar, announcement_text) VALUES ('3f45003a-6fa1-575e-97fb-f7792badf2a7', '#b5651d', '#b5651d', 'Bricolage Grotesque', 'Work Sans', '{"preset": "koffie", "settings": {"background": "#f4ede4", "text": "#2b1d14", "button_style": "pill", "corner_radius": "large", "header_layout": "left", "logo_height": 44, "show_search": false, "hero_style": "boxed", "heading_style": "left", "card_style": "framed", "container": "normal", "caps": false}, "product_page": {"show_delivery": true, "delivery_text": "Vers gebrand, door je brievenbus", "show_returns": false, "show_payment_icons": true, "show_related": true, "related_title": "Ook proberen"}}'::jsonb, true, true, now(), true, 'online', true, 'Demowinkel van SellQo: bestellen werkt, maar er wordt niets gebrand, verzonden of aangerekend.');
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('3f45003a-6fa1-575e-97fb-f7792badf2a7', 'hero', 'Vers gebrand, elke dinsdag', 'Specialty koffie van kleine boerderijen, gebrand in Leuven', '{"image_url": "", "button_text": "Kies je bonen", "button_link": "/producten", "text_alignment": "left", "overlay_opacity": 0.4}'::jsonb, '{}'::jsonb, 0, true);
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('3f45003a-6fa1-575e-97fb-f7792badf2a7', 'usp_bar', null, null, '{"items": [{"icon": "clock", "title": "Vers gebrand", "text": "Maximaal 7 dagen oud"}, {"icon": "truck", "title": "Door de brievenbus", "text": "Gratis vanaf €35"}, {"icon": "leaf", "title": "Direct van de boer", "text": "Eerlijke prijzen"}]}'::jsonb, '{"style": {"background": "accent", "spacing": "compact"}}'::jsonb, 1, true);
