INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('3f45003a-6fa1-575e-97fb-f7792badf2a7', 'text_image', 'Onze branderij', null, '{"text": "Elke dinsdag branden we in kleine hoeveelheden. Je koffie vertrekt dezelfde week, zodat hij vers bij je aankomt. Kies je maling bij het bestellen.", "image_url": "", "image_position": "right", "button_text": "Bekijk alles", "button_link": "/producten"}'::jsonb, '{}'::jsonb, 3, true);
INSERT INTO homepage_sections (tenant_id, section_type, title, subtitle, content, settings, sort_order, is_visible) VALUES ('3f45003a-6fa1-575e-97fb-f7792badf2a7', 'faq', 'Goed om te weten', null, '{"items": [{"question": "Welke maling moet ik kiezen?", "answer": "Bonen als je zelf maalt. Filter voor V60 of filterkoffie, espresso voor je espressomachine."}, {"question": "Hoe lang blijft koffie vers?", "answer": "Het lekkerst binnen 4 weken na het branden. Bewaar luchtdicht en koel."}, {"question": "Is dit een echte winkel?", "answer": "Nee, dit is een demowinkel van SellQo. Je kan alles uitproberen, ook afrekenen, maar er wordt niets gebrand, verzonden of aangerekend."}]}'::jsonb, '{}'::jsonb, 4, true);